def select_next_node(graph, unvisited_nodes):
    import numpy as np

    pre = graph.graph.get('precomputed', {})
    bridge_ratio = pre.get('bridge_ratio_high_bc', 0.1)
    degree_variance = pre.get('degree_variance', 1)
    max_core_k = pre.get('max_core_k', 1)

    unvisited_set = set(unvisited_nodes)

    # Personalized PageRank-like score biased towards unvisited neighbors
    alpha = 0.85  # teleportation factor
    scores = {}
    for n in unvisited_nodes:
        nbrs = set(graph.neighbors(n))
        unvisited_nbrs = nbrs & unvisited_set
        deg = graph.nodes[n].get('degree', 0)
        unvisited_deg = len(unvisited_nbrs)

        # Personalization vector weight to unvisited neighbors ratio
        personalization = unvisited_deg / (deg + 1e-9)

        # Base score incorporates bridgeratio and degree variance scaling
        base_score = alpha * personalization + (1 - alpha) * (degree_variance / (degree_variance + 10))

        scores[n] = base_score

    # Normalize scores
    vals = np.array(list(scores.values()))
    mn, mx = vals.min(), vals.max()
    if mx - mn < 1e-9:
        norm_scores = {k: 1.0 for k in scores}
    else:
        norm_scores = {k: (v - mn) / (mx - mn) for k, v in scores.items()}

    # Penalty terms: clustering and core number penalize the score
    clustering = {n: graph.nodes[n].get('clustering', 0) for n in unvisited_nodes}
    core_number = {n: graph.nodes[n].get('core_number', 0) for n in unvisited_nodes}

    # Normalize clustering and core_number
    clust_vals = np.array(list(clustering.values()))
    core_vals = np.array(list(core_number.values()))

    def normalize(arr):
        mn_, mx_ = arr.min(), arr.max()
        if mx_ - mn_ < 1e-9:
            return np.ones_like(arr)
        return (arr - mn_) / (mx_ - mn_)

    norm_clust = normalize(clust_vals)
    norm_core = normalize(core_vals)

    # Combine penalty with dynamic weighting based on bridge_ratio and max_core_k
    penalty_w_clust = 0.5 + bridge_ratio
    penalty_w_core = 0.5 * (max_core_k / (max_core_k + 5))

    penalties = {n: penalty_w_clust * c + penalty_w_core * core_number[n] for n, c in zip(unvisited_nodes, norm_clust)}

    # Final score: normalized base score minus penalties
    final_scores = {n: norm_scores[n] - penalties[n] for n in unvisited_nodes}

    # Select node with max final score
    next_node = max(final_scores, key=final_scores.get)
    return next_node

def select_next_node(graph, unvisited_nodes):
    def score(node):
        attrs = graph.nodes[node]
        return attrs['core_number'] * attrs['eigenvector'], attrs['betweenness']
    next_node = max(unvisited_nodes, key=score)
    return next_node
